// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * Dishes added to the cart from the card: the live cart count over a grid of cards, each with a picture, name,
 * weight, price and a quantity field named after the dish beside the add button. Axes: media (image, none),
 * tone.
 */
import { type ReactNode } from "react";
import { Box, Grid, Group, Stack, Text } from "../compose";
import { AddQty } from "../components/add-qty";
import { CartCount } from "../components/cart-count";
import { EmptyState } from "../components/empty-state";
import { MediaFrame } from "../components/media-frame";
import { SectionFrame } from "../components/section-frame";
import { fmtMoney, tpl } from "../utils";
import type { Dish, FoodLabels } from "./dish-showcase.types";

export type DishCartGridProps = {
  id: string;
  title: string;
  lead?: string;
  dishes: Dish[];
  empty?: string;
  labels: FoodLabels;
  count?: number;
  media?: "image" | "none";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function DishCartGrid({
  id,
  title,
  lead = "",
  dishes,
  empty = "",
  labels,
  count = 0,
  media = "image",
  tone = "default",
  landmarkLabel,
}: DishCartGridProps) {
  return (
    <SectionFrame id={id} title={title} lead={lead} tone={tone} landmarkLabel={landmarkLabel}>
      {((dishes?.length ?? 0) === 0) ? (
        <EmptyState icon="shopping-bag" title={empty} />
      ) : (
        <Stack gap="4" align="stretch">
          <Group justify="end">
            <CartCount count={count} label={labels.inCart} />
          </Group>
          <Grid cols="1-3" className="gap-4" data-slot="items">
            {(dishes ?? []).map((d) => (
              <Stack key={d.id} gap="4" className="rounded bg-card inset-ring inset-ring-border overflow-hidden pb-4" data-slot="item">
                {((media as string) === "image") ? (
                  <MediaFrame alt={d.name} />
                ) : null}
                <Stack gap="2" className={(((media as string) === "image") ? "px-4" : "px-4 pt-4")}>
                  <Group gap="2" align="baseline" justify="between">
                    <Text size="base" weight="semibold">
                      {d.name}
                    </Text>
                    <Text size="xs" className="text-muted-foreground">
                      {d.weight}
                    </Text>
                  </Group>
                  <Text size="lg" weight="bold">
                    {fmtMoney(d.price, d.currency)}
                  </Text>
                </Stack>
                <Box className="px-4">
                  <AddQty name={tpl("{0}-qty-{1}", id, d.id)} dish={d.name} labels={labels} />
                </Box>
              </Stack>
            ))}
          </Grid>
        </Stack>
      )}
    </SectionFrame>
  );
}
